import json
from pathlib import Path
out=Path(__file__).parent/'dist/lessons.js'
def step(title, instruction, text='', seconds=60, check='', notes=None):
 d=dict(title=title,instruction=instruction,text=text,seconds=seconds,check=check)
 if notes is not None:d['notes']=notes
 return d
control='Сегодня я хочу рассказать об одной простой мысли. Для меня важно говорить спокойно, ясно и точно. Я могу делать паузы, выбирать нужные слова и сохранять естественный голос. Мне не нужно спешить или говорить громче, чтобы быть услышанным.'
speech_topics=[
 ('Найти свой голос','Свобода','Расскажи о себе и своих увлечениях. Представь одного знакомого слушателя.','Мм-хм. Да, я понял. Смотрите, здесь важно объяснить. Я бы предложил другой вариант.'),
 ('Говорить без нажима','Свобода','Объясни, как проходит твой обычный день. Сохраняй обычную разговорную громкость.','Мне не нужно давить голосом. Я могу говорить спокойно. Моя мысль важна сама по себе.'),
 ('Сохранить лёгкость','Свобода','Прочитай контрольный текст, затем скажи то же самое своими словами.',control),
 ('Чётко, но не жёстко','Дикция','Объясни, как освоить новый навык. Не ускоряй перечисления.','Сначала мы выбираем цель. Затем пробуем один понятный шаг. После практики проверяем результат.'),
 ('Открытые гласные','Дикция','За одну минуту расскажи о любимой музыке. Гласные звучат свободно, согласные не теряются.','Я говорю понятно. Мне не нужно спешить. В каждом слове есть смысл.'),
 ('Живая речь','Дикция','Скажи одну мысль сначала другу, потом новому знакомому. Сохрани понятность в обоих вариантах.','Качество начинается с внимания. Мы обсуждаем задачу заранее. Так ожидания и результат становятся ближе.'),
 ('Пауза после мысли','Подача','Ответь на вопрос: почему качественная работа требует времени? После мысли выдержи паузу.','Сначала нужно понять задачу. / Потом выбрать решение. / И только после этого — приступать к работе.'),
 ('Главное слово','Подача','Расскажи о своём увлечении. В каждом предложении выбери только одно главное слово.','Мы обсуждаем ЗАДАЧУ заранее. Мы ОБСУЖДАЕМ задачу заранее. Мы обсуждаем задачу ЗАРАНЕЕ.'),
 ('Три варианта подачи','Подача','Одно приветствие произнеси тепло, делово и энергично. Не увеличивай громкость резко.','Добрый день. Рад вас видеть. Давайте обсудим, какой результат вы хотите получить.'),
 ('Спокойно обозначить границу','Живая речь','Вежливо откажись от неудобной просьбы. Коротко назови причину и предложи другой вариант.','Сегодня я не смогу помочь. У меня уже есть другие планы. Давайте договоримся на другой день.'),
 ('Голос для камеры','Живая речь','Подготовь речь на 30 секунд: одна проблема, один пример, один вывод. Сделай три дубля.','Сложный навык начинается с простого действия. Выберите один небольшой шаг. Повторите его внимательно и посмотрите, что изменилось.'),
 ('Свой голос в жизни','Живая речь','Прочитай контрольный текст и сравни с первой записью. Затем расскажи историю о любимом занятии.',control)
]
lessons=[]
for i,(title,focus,real,text) in enumerate(speech_topics):
 steps=[step('Настроиться', 'Сядь удобно. Отпусти плечи и челюсть. Дыши обычно, без задержек и больших вдохов. Произнеси короткую фразу на удобном выдохе.', 'Я здесь. Я не тороплюсь.',60,'Дыхание спокойное, плечи не поднимаются.'),step('Найти лёгкую высоту','Скажи «мм-хм», как спокойное согласие. Затем произнеси фразу с той же лёгкостью. Повтори 5 раз, оставляя отдых между попытками.','Мм-хм. Да, я понял. Давайте обсудим.',60,'Не изображай низкий голос. В горле нет усилия.'),step('Мягкий разогрев','Несколько раз мягко погуди «ммм» по 2–3 секунды. Между повторами отдыхай. Если получается легко, добавь короткую губную трель.','М-м-м. / Бр-р-р. / М-м-м.',60,'Небольшая громкость. Если трель не получается — оставь «ммм».'),step('Разбудить артикуляцию','Произнеси слоги медленно 5 раз. Потом скажи обычное предложение. Двигай губами свободно, не выталкивай звук.','МА — МЭ — МИ — МО — МУ.\nЯ говорю спокойно и понятно.',60,'Речь после слогов остаётся естественной.'),step('Одна скороговорка','Прочитай медленно 3 раза. Сделай паузу. Ещё 3 раза обычным голосом. Чередуй с отдыхом. Ускорь немного только после трёх чистых повторов.','На дворе трава, на траве дрова.\nНе руби дрова на траве двора.',240,'Цель — ясность, а не рекорд скорости.'),step('Смысл и паузы','Прочитай текст 3 раза. После законченной мысли оставь 2 секунды тишины. Затем перескажи. Повторяй с отдыхом, выбирая одно главное слово во фразе.',text,240,'Не опускай высоту силой. Заканчивай мысль спокойно.'),step('Перенести в разговор',real+' Говори 30–60 секунд, остановись, подумай о паузах и повтори. Если стоишь на месте, запиши один дубль.','Одна мысль → один пример → вывод.',240,'Говори человеку, а не изображай диктора.'),step('Замечать результат','Вспомни: где спешил, где напрягался, где выдержал паузу? Выбери одно улучшение для следующего раза. Запись можно сделать или прослушать после остановки.', 'Сегодня у меня получилось…\nВ следующий раз я обращу внимание на…',120,'Оцени факты, а не «красивый ли у меня тембр».')]
 lessons.append(dict(id=f'speech-{i+1}',course='speech',title=title,focus=focus,steps=steps))
vocal_topics=[
 ('Начать мягко','Лёгкий звук','ммм',[0,2,0],'Пой негромко, как будто спокойно отвечаешь человеку.'),
 ('Ровный звук','Устойчивость','у',[0,0,0],'Держи каждый короткий звук ровно, без прибавления громкости.'),
 ('Слышать направление','Слух','му',[0,2,4,2,0],'Заметь: мелодия поднимается и возвращается. Не тянись к ноте шеей.'),
 ('Три ступени','Интонация','ма',[0,2,4,2,0],'Сначала прослушай рисунок, затем повтори по одному звуку.'),
 ('Спускаться свободно','Интонация','ну',[4,2,0],'Начни на удобной высоте и мягко спустись. Не дави на последнюю ноту.'),
 ('Пять звуков','Интонация','му',[0,2,4,5,7,5,4,2,0],'Если верх неудобен, опусти пример кнопкой «Ниже» или вернись к трём нотам.'),
 ('Ноты в пульсе','Ритм','ма',[0,0,2,2,4,2,0],'Повтори рисунок в одинаковом темпе. Паузы — часть музыки.'),
 ('Одна мелодия — две гласные','Гласные','у → о',[0,2,4,2,0],'Один повтор на «у», следующий на «о». Сохрани лёгкость, не расширяй рот силой.'),
 ('Тише и выразительнее','Динамика','му',[0,4,2,0],'Один повтор обычным тихим голосом, второй чуть выразительнее. Не переходи на крик.'),
 ('Слова на мелодии','Фраза','Я говорю легко',[0,2,4,2,0],'Сначала пропой слоги, затем свои слова. Не жертвуй лёгкостью ради текста.'),
 ('Придумать ответ','Музыкальность','му',[0,2,4,2,0],'После примера придумай короткий ответ из этих же звуков. Закончи на первом.'),
 ('Собрать свою фразу','Итог','на',[0,4,7,4,0],'Сделай 3 коротких варианта: ровный, тёплый, энергичный. Не увеличивай диапазон ради результата.')
]
for i,(title,focus,syllable,notes,tip) in enumerate(vocal_topics):
 lessons.append(dict(id=f'vocal-{i+1}',course='vocal',title=title,focus=focus,steps=[step('Проверить лёгкость','Произнеси пару обычных фраз. Затем мягко погуди «ммм» 3 раза по 2 секунды с отдыхом. Никакого искусственного баса.','Сегодня я пою на удобной высоте.',60,'Если голос осип или говорить неприятно — отложи вокальную практику.'),step('Сначала услышать','Послушай пример. Мысленно проследи движение звуков. Высоту примера можно менять. В режиме слушания пример прозвучит один раз перед паузой для повтора.','Слушай → представь → повтори.',60,'Пример — ориентир для слуха, не требование брать неудобные ноты.',notes),step('Повторить мягко',f'Повтори рисунок на «{syllable}» 3 раза. Между повторами отдыхай столько же, сколько пел. {tip}',syllable,120,'Если появляется нажим — сделай тише, короче или ниже.',notes),step('Представить и проверить','Вспомни рисунок из предыдущего шага. Сначала мысленно услышь его, затем мягко пропой без примера. Только после этого нажми «Проверить пример». В режиме слушания образец перед этим упражнением не включается. Сделай 3 подхода с отдыхом.',syllable,120,'Сравни направление мелодии и ровность начала, а не чужой тембр.',notes),step('Перенести в песню','Выбери одну короткую знакомую фразу из песни на удобной высоте. Сначала произнеси её, затем мягко пропой. После остановки можно записать дубль.','Текст → ритм → мелодия.',120,'Цель — лёгкость и понятная фраза, а не максимальная громкость.'),step('Закончить спокойно','Скажи обычную фразу и сравни ощущения с началом. Отметь, что получилось. Сегодня достаточно.','Голос остаётся лёгким. Я могу говорить без усилия.',60,'Не продолжай через першение, боль или усталость.')]))
for lesson in lessons:
 if lesson['course']=='vocal':
  lesson['steps'][3]['recall']=True
piano_topics=[
 ('Где находится До','Клавиатура','Чёрные клавиши повторяются группами по две и по три. До — белая клавиша слева от пары чёрных.','Найди три разных До на своём инструменте. На экранной клавиатуре найди До4.',[60,72],'До → Ре → Ми → Фа → Соль → Ля → Си.'),
 ('Полутон и тон','Расстояния','Полутон — шаг до ближайшей клавиши, включая чёрные. Тон — два таких шага.','Сыграй До → До-диез → Ре. Между До и Ре — тон.',[60,61,62],'До → До♯ → Ре'),
 ('Ми–Фа и Си–До','Расстояния','Между Ми и Фа, Си и До нет чёрной клавиши. Они уже соседи: расстояние — полутон.','Сыграй Ми–Фа, затем Си–До. Найди такие пары в другой октаве.',[64,65,71,72],'Ми — Фа. Си — До.'),
 ('Пять пальцев','Движение','Нумерация пальцев: большой — 1, указательный — 2, средний — 3, безымянный — 4, мизинец — 5.','Правой рукой сыграй До–Ре–Ми–Фа–Соль пальцами 1–2–3–4–5. Обратно 5–4–3–2–1. Медленно, кисть свободна.',[60,62,64,65,67,65,64,62,60],'1 — 2 — 3 — 4 — 5 — 4 — 3 — 2 — 1'),
 ('Гамма как маршрут','Гаммы','До мажор: тон, тон, полутон, тон, тон, тон, полутон. На клавишах это белые ноты от До до До.','Прослушай гамму. На инструменте сначала сыграй первые пять нот. Полную октаву разучи отдельно медленно.',[60,62,64,65,67,69,71,72],'До — Ре — Ми — Фа — Соль — Ля — Си — До'),
 ('Ля минор','Тональность','В натуральном Ля миноре те же белые клавиши, что в До мажоре, но точка покоя — Ля.','Сыграй Ля–Си–До–Ре–Ми, затем вернись к Ля. Слушай ощущение завершения.',[57,59,60,62,64,62,60,59,57],'Ля — Си — До — Ре — Ми — Фа — Соль — Ля'),
 ('Аккорд из трёх нот','Аккорды','Трезвучие строим через одну ступень гаммы. В До мажоре 1, 3, 5 — До, Ми, Соль.','Сыграй До–Ми–Соль по очереди, затем вместе. В практике есть отдельная кнопка аккорда C.',[60,64,67],'C = До + Ми + Соль'),
 ('Мажор и минор','Аккорды','C: До–Ми–Соль. Cm: До–Ми-бемоль–Соль. Меняется средняя нота, а вместе с ней — окраска.','Сравни C и Cm. Затем Am: Ля–До–Ми. Попробуй узнать смену окраски на слух.',[60,64,67,60,63,67],'C → Cm. Am = Ля + До + Ми.'),
 ('Обращения','Удобные переходы','Один набор нот можно расположить по-разному. До–Ми–Соль, Ми–Соль–До, Соль–До–Ми — всё C.','Сыграй три положения аккорда C. Не тяни пальцы: перемещай руку целиком между положениями.',[60,64,67,64,67,72,67,72,76],'До–Ми–Соль → Ми–Соль–До → Соль–До–Ми'),
 ('Две руки','Координация','Левая играет корень аккорда, правая — сам аккорд. Начни с одного нажатия на четыре счёта.','На инструменте: левая До, правая До–Ми–Соль. Затем левая Ля, правая Ля–До–Ми. По 4 счёта на аккорд.',[48,60,64,67,45,57,60,64],'Левая — основа. Правая — аккорд.'),
 ('Четыре аккорда','Аккомпанемент','C–G–Am–F: До–Ми–Соль; Соль–Си–Ре; Ля–До–Ми; Фа–Ля–До.','Разучи каждый отдельно. Затем играй по одному аккорду на четыре счёта, без спешки.',[60,64,67,55,59,62,57,60,64,53,57,60],'C → G → Am → F'),
 ('Первая музыкальная фраза','Своя музыка','Поверх C начни мелодию с До, Ми и Соль. Между ними можно добавить Ре или Фа. Пауза тоже часть фразы.','Сыграй C, затем придумай мелодию из 3–5 нот. Повтори её дважды, изменив только окончание.',[60,64,67,64,62,60],'Один мотив → повтор → новое окончание.')
]
for i,(title,focus,theory,practice,notes,text) in enumerate(piano_topics):
 lessons.append(dict(id=f'piano-{i+1}',course='piano',title=title,focus=focus,home=True,steps=[step('Понять одну вещь',theory,text,60,'Проговори смысл своими словами.'),step('Сначала послушать','Нажми «Послушать пример». Проследи порядок нот. Экранные клавиши находятся в разделе «Практика».',text,60,'Учимся через звук, затем даём ему название.',notes),step('Сделать руками',practice+' Повтори медленно 5 раз. Если ошибся, сократи фрагмент.',text,180,'Экран поможет найти ноты; движения рук осваивай на настоящих клавишах.',notes),step('Проверить навык','Отвернись от подсказки и повтори задание. Затем объясни себе, что именно ты сыграл. Если не получается — вернись на предыдущий шаг.','Понял → сыграл → повторил без подсказки.',60,'Отмечай урок освоенным после практики на инструменте, а не после чтения.')]))
music_topics=[
 ('Пульс и ритм','Ритм','Пульс — ровные доли. Ритм — рисунок звуков и пауз внутри них.','При темпе 80 отсчитай четыре доли. Сначала хлопок на каждую, потом только на 1 и 3.','Раз — два — три — четыре.'),
 ('Первый бит','Ритм','В редакторе восемь шагов: две восьмые на долю, один такт 4/4. Бочка на 1 и 5, хлопок на 3 и 7.','Открой практику. Нажми «Пример бита», затем воспроизведение. Измени один шаг и сравни.','Бочка: 1 и 5. Хлопок: 3 и 7. Хэт: через шаг.'),
 ('Музыка вокруг аккордов','Гармония','C–G–Am–F — четыре разных опоры. Держи каждый аккорд четыре счёта, прежде чем менять.','Послушай аккорды в практике. Придумай, где в этой последовательности мог бы начинаться припев.','C → G → Am → F'),
 ('Мотив из трёх нот','Мелодия','Короткая узнаваемая мысль сильнее случайного перебора. Возьми До, Ми и Соль.','Придумай порядок из четырёх звуков, используя только До, Ми и Соль. Повтори и измени последнюю ноту.','До — Ми — Соль — Ми.\nДо — Ми — Соль — До.'),
 ('Оставить место голосу','Аранжировка','Если каждый инструмент играет всё время, мелодии тесно. Сделай паузы в сопровождении.','В редакторе убери половину ударов хэта. Под полученный рисунок проговори короткую фразу.','Меньше звуков → больше места для мысли.'),
 ('Куплет и припев','Форма','Развитие можно создать плотностью и ритмом, сохранив те же аккорды.','Сделай редкий бит для куплета. Затем добавь хэт для припева. Сохрани две версии отдельными файлами проекта.','Куплет — пространство. Припев — движение.'),
 ('Текст в ритме','Песня','Начни с разговорной фразы. Найди естественные ударения. Не ломай слово ради сильной доли.','Скажи «Я выбираю свой путь». Придумай свой вариант той же длины, затем напой на трёх нотах.','Я выбираю свой путь.\nЯ остаюсь собой.'),
 ('Собрать эскиз','Итог','Эскиз — понятная идея: ритм, гармония и одна ведущая фраза. Не нужно сразу делать готовый трек.','Выбери темп, собери бит, сыграй аккорды и напой мотив. Запиши голос отдельно в практике. Скачай проект бита и запись.','Темп → бит → аккорды → голос → сохранить.')
]
